# ===========================================================================
#  VUA TRO CHOI - BO CAI DAT TU DONG STEAM TOC DO CAO (POWERSHELL 1-LINER)
#  Phan phoi ban quyen tu dong | Xac thuc qua Google Sheets 0d
# ===========================================================================

[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$Host.UI.RawUI.WindowTitle = "VUA TRO CHOI - Kich Hoat He Thong Steam"

# 1. Tu dong kiem tra va tu dong nang quyen Administrator (UAC Popup)
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) {
    Write-Host ""
    Write-Host " [!] Chuong trinh can quyen Administrator de cau hinh he thong." -ForegroundColor Yellow
    Write-Host " [!] Dang yeu cau cap quyen Administrator (UAC)..." -ForegroundColor Yellow
    
    if ($PSCommandPath) {
        Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`"" -Verb RunAs
    } else {
        $onlineCmd = "irm https://raw.githubusercontent.com/kienzexal-del/vuatrochoi/main/install.ps1 | iex"
        Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -Command `"$onlineCmd`"" -Verb RunAs
    }
    exit
}

Clear-Host
Write-Host ""
Write-Host " ===========================================================================" -ForegroundColor Yellow
Write-Host "    [VUA TRO CHOI] - HE THONG KICH HOAT STEAM FULL TOC DO                  " -ForegroundColor Yellow
Write-Host " ===========================================================================" -ForegroundColor Yellow
Write-Host ""

# 2. Cau hinh Link API Google Apps Script cua ban
$API_URL = "https://script.google.com/macros/s/AKfycbzsJ4SvFtnCRROeB3SZHNcq65oReT-wlBQJlwF9eG4WUsDI9cJT4JuXLLuH9Y6TYZdRJg/exec"

# 3. Lay ma phan cung may tinh (HWID UUID)
$uuid = (Get-CimInstance Win32_ComputerSystemProduct -ErrorAction SilentlyContinue).UUID
if (-not $uuid -or $uuid -eq "FFFFFFFF-FFFF-FFFF-FFFF-FFFFFFFFFFFF") {
    $cpu = (Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue | Select-Object -First 1).ProcessorId
    $mb = (Get-CimInstance Win32_BaseBoard -ErrorAction SilentlyContinue).SerialNumber
    $raw = "$cpu-$mb"
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($raw)
    $uuid = ([System.BitConverter]::ToString($sha.ComputeHash($bytes))).Replace("-", "").Substring(0, 32)
}

Write-Host " [i] Ma thiet bi cua ban (HWID): $uuid" -ForegroundColor DarkGray
Write-Host ""

# 4. Yeu cau nhap Key (An mat khau dang *****)
$promptText = " [?] Vui long nhap Ma Ban Quyen (License Key) hoac Mat Khau Admin"
try {
    $sec = Read-Host -Prompt $promptText -AsSecureString
    $key = [System.Net.NetworkCredential]::new("", $sec).Password
} catch {
    $key = Read-Host -Prompt $promptText
}
$key = $key.Trim()

if ([string]::IsNullOrWhiteSpace($key)) {
    Write-Host ""
    Write-Host " [-] Ban chua nhap ma ban quyen. Chuong trinh tam dung." -ForegroundColor Red
    Write-Host ""
    Read-Host " Nhan Enter de thoat..."
    exit
}

# 5. Xac thuc voi may chu Google Apps Script
Write-Host ""
Write-Host " [+] Dang ket noi may chu xac thuc ban quyen..." -ForegroundColor Cyan

if ($API_URL -ne "__GOOGLE_SCRIPT_WEBHOOK_URL__" -and -not [string]::IsNullOrWhiteSpace($API_URL)) {
    try {
        $verifyUrl = "{0}?action=verify&key={1}&hwid={2}" -f $API_URL, [Uri]::EscapeDataString($key), [Uri]::EscapeDataString($uuid)
        $resp = Invoke-RestMethod -Uri $verifyUrl -Method Get -TimeoutSec 15
        
        if (-not $resp.success) {
            Write-Host ""
            Write-Host " ===========================================================================" -ForegroundColor Red
            Write-Host "  [-] XAC THUC THAT BAI: $($resp.message)" -ForegroundColor Red
            Write-Host " ===========================================================================" -ForegroundColor Red
            Write-Host ""
            Read-Host " Nhan Enter de thoat..."
            exit
        }

        Write-Host " [OK] $($resp.message)" -ForegroundColor Green
        if ($resp.customer) {
            Write-Host " [i] Xin chao quy khach: $($resp.customer)" -ForegroundColor Green
        }
    } catch {
        Write-Host " [-] Khong the ket noi den may chu xac thuc: $($_.Exception.Message)" -ForegroundColor Red
        Write-Host "     Vui long kiem tra ket noi mang va thu lai." -ForegroundColor Yellow
        Read-Host " Nhan Enter de thoat..."
        exit
    }
} else {
    Write-Host " [!] Che do thu nghiem cuc bo khi chua gan link API Google Script." -ForegroundColor Yellow
    if ($key -ne "TEST" -and $key -ne "VUATROCHOI@2026") {
        Write-Host " [-] O che do test, vui long nhap 'TEST' hoac 'VUATROCHOI@2026' de tiep tuc." -ForegroundColor Red
        Read-Host " Nhan Enter de thoat..."
        exit
    }
    Write-Host " [OK] Xac thuc ma Test thanh cong!" -ForegroundColor Green
}

# 6. Trien khai goi cai dat vao C:\ProgramData\VuaTroChoi
Write-Host ""
Write-Host " [+] Dang thiet lap he thong VUA TRO CHOI vao may..." -ForegroundColor Cyan
$installDir = "C:\ProgramData\VuaTroChoi"
if (-not (Test-Path $installDir)) {
    New-Item -ItemType Directory -Path $installDir -Force | Out-Null
}

# Dung tien trinh cu neu dang chay
Get-Process -Name "winws" -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
taskkill.exe /f /im winws.exe 2>$null | Out-Null

# Giai nen Payload Base64
$payloadB64 = ""
$zipBytes = [Convert]::FromBase64String($payloadB64)
$tempZip = Join-Path $env:TEMP "vtch_temp.zip"
[System.IO.File]::WriteAllBytes($tempZip, $zipBytes)

Add-Type -AssemblyName System.IO.Compression.FileSystem
$zipArchive = [System.IO.Compression.ZipFile]::OpenRead($tempZip)
foreach ($entry in $zipArchive.Entries) {
    $targetPath = Join-Path $installDir $entry.FullName
    if ($entry.FullName.EndsWith('/') -or $entry.FullName.EndsWith('\')) {
        if (-not (Test-Path $targetPath)) { New-Item -ItemType Directory -Path $targetPath -Force | Out-Null }
    } else {
        $parent = Split-Path $targetPath -Parent
        if (-not (Test-Path $parent)) { New-Item -ItemType Directory -Path $parent -Force | Out-Null }
        [System.IO.Compression.ZipFileExtensions]::ExtractToFile($entry, $targetPath, $true)
    }
}
$zipArchive.Dispose()
Remove-Item $tempZip -Force -ErrorAction SilentlyContinue

# 7. Toi uu hoa duong truyen mang va khac phuc triet de loi chan Steam o may moi
Write-Host " [+] Dang toi uu hoa duong truyen mang he thong..." -ForegroundColor Cyan
Get-NetAdapter | Where-Object Status -eq 'Up' | ForEach-Object {
    Set-DnsClientServerAddress -InterfaceAlias $_.Name -ServerAddresses ('8.8.8.8','8.8.4.4','2001:4860:4860::8888','2001:4860:4860::8844') -ErrorAction SilentlyContinue
}
Clear-DnsClientCache

$hostsPath = "$env:SystemRoot\System32\drivers\etc\hosts"
$marker = "# Steam Clean IPs"
$currentHosts = Get-Content -Path $hostsPath -Raw -ErrorAction SilentlyContinue
if ($currentHosts -notmatch [regex]::Escape($marker)) {
    $steamEntries = @"

$marker
23.15.142.182 store.steampowered.com
23.15.140.216 steamcommunity.com
23.50.30.213 help.steampowered.com
96.7.111.132 checkout.steampowered.com
"@
    Add-Content -Path $hostsPath -Value $steamEntries -Encoding UTF8 -ErrorAction SilentlyContinue
}
ipconfig /flushdns | Out-Null

# 8. Cai dat tac vu khoi dong ngam Windows Task Scheduler
Write-Host " [+] Dang dang ky dich vu tu chay ngam cung Windows (Task Scheduler)..." -ForegroundColor Cyan
$taskName = "Zapret_System_Daemon"
$vbsPath = Join-Path $installDir "zapret_silent.vbs"
$taskRun = "wscript.exe `"$vbsPath`""

schtasks.exe /create /f /tn "$taskName" /tr "$taskRun" /sc onlogon /rl highest | Out-Null

# 9. Khoi chay tien trinh ngay lap tuc qua Task Scheduler (Chay quyen cao nhat)
Write-Host " [+] Dang khoi dong tien trinh he thong..." -ForegroundColor Cyan
schtasks.exe /run /tn "$taskName" | Out-Null
Start-Process -FilePath "wscript.exe" -ArgumentList "`"$vbsPath`"" -ErrorAction SilentlyContinue

Start-Sleep -Seconds 2

# 10. Kiem tra ket qua
$isRunning = Get-Process -Name "winws" -ErrorAction SilentlyContinue
Write-Host ""
Write-Host " ===========================================================================" -ForegroundColor Green
Write-Host "    [VUA TRO CHOI] HOAN TAT KICH HOAT HE THONG THANH CONG!                 " -ForegroundColor Green
Write-Host " ===========================================================================" -ForegroundColor Green
Write-Host "  [+] Dich vu he thong: DA DANG KY TU CHAY KHI BAT MAY                     " -ForegroundColor White
Write-Host "  [+] Tien trinh nen: $(if ($isRunning) { 'DANG CHAY (PID: ' + $isRunning.Id + ')' } else { 'SAN SANG' })" -ForegroundColor White
Write-Host "  [+] Trang thai: DA MO KHOA TOAN DIEN MAY CHU STEAM                       " -ForegroundColor White
Write-Host " ===========================================================================" -ForegroundColor Green
Write-Host ""
Write-Host " Bay gio ban co the mo Steam va tai game ngay lap tuc!" -ForegroundColor Yellow
Write-Host ""
Read-Host " Nhan Enter de dong cua so..."